<script setup>
import { computed } from "vue";
import axios from 'axios';
import { storeToRefs } from "pinia/dist/pinia";
import { XIcon } from "@heroicons/vue/solid";
import { usePlatformStore } from "../../../Stores/platform";
import { useUserStore } from "../../../Stores/user";
import MuButton from "../../_Units/Button/MuButton";

const props = defineProps({
    disableClose: {
        type: Boolean,
        default: false
    }
})

const platformStore = usePlatformStore();
const { membershipUpgradeModal } = storeToRefs(platformStore);
const userStore = useUserStore();
const { userSubscriptionIntervalType, isLifetimeMember } = storeToRefs(userStore);

const modalClose = () => {
    !membershipUpgradeModal.value.disableClose && platformStore.closeMembershipUpgradeModal();
}

const onWrapperClick = (event) => {
    if (event.target.id === 'modal-wrapper') {
        modalClose();
    }
}
const isMonthly = computed(() => {
    return userSubscriptionIntervalType.value === 'month'
})

const isYearly = computed(() => {
    return userSubscriptionIntervalType.value === 'year'
})

const price = computed(() => {
    if(isMonthly.value) {
        return 5;
    } else if(isYearly.value) {
        return 20;
    } else if(isLifetimeMember.value){
        return 40;
    }
})

const interval = computed(() => {
    if(isMonthly.value) {
        return 'more / Month';
    } else if(isYearly.value) {
        return '/ Month';
    } else if(isLifetimeMember.value){
        return '/ Year';
    }
})

const intervalDesc = computed(() => {
    if(isMonthly.value) {
        return 'Pay as you go.';
    } else if(isYearly.value) {
        return 'Billed at $240 per year.';
    }
})

const consentText = computed(() => {
    if(isMonthly.value) return 'By choosing "Pay Monthly," I understand that my next renewal will be $40 for Musora+ with Songs.';
})

const upgradeNow = async() => {
    const redirectURL = await axios.post('/ecommerce/subscription/upgrade');

    if(redirectURL.data?.url){
        window.location.href = redirectURL.data.url;
    }
    else{
        window.location.reload();
    }
}
</script>
